// cepm helper: reloads unpacked extensions on request from the cepm native
// messaging host. Generated by "cepm setup"; do not edit by hand.

const HOST_NAME = "com.github.be_hase.cepm";
const KEEPALIVE_ALARM = "cepm-keepalive";

let port = null;
let backoffMs = 1000;

function connect() {
  if (port) return;
  port = chrome.runtime.connectNative(HOST_NAME);
  port.onMessage.addListener(onMessage);
  port.onDisconnect.addListener(() => {
    // Fires both when the host exits (Chrome quitting) and when the host
    // binary is missing/misconfigured (chrome.runtime.lastError set).
    void chrome.runtime.lastError;
    port = null;
    scheduleReconnect();
  });
  post({ type: "hello", helperVersion: chrome.runtime.getManifest().version });
}

function scheduleReconnect() {
  // Best-effort: the service worker may be killed before this fires, in
  // which case the keepalive alarm below revives us and reconnects.
  const delay = backoffMs;
  backoffMs = Math.min(backoffMs * 2, 60000);
  setTimeout(connect, delay);
}

function post(msg) {
  if (!port) return;
  try {
    port.postMessage(msg);
  } catch (e) {
    // Port died between the check and the send; onDisconnect will handle it.
  }
}

async function onMessage(msg) {
  switch (msg.type) {
    case "helloAck":
      backoffMs = 1000;
      break;
    case "ping":
      post({ type: "pong", seq: msg.seq });
      break;
    case "reload":
      await handleReload(msg);
      break;
    case "listExtensions":
      await handleList(msg);
      break;
  }
}

async function handleReload(msg) {
  const results = [];
  let reloadSelf = false;
  for (const id of msg.extensionIds || []) {
    if (id === chrome.runtime.id) {
      // We cannot setEnabled ourselves; use runtime.reload after replying.
      reloadSelf = true;
      results.push({ id, status: "reloaded" });
      continue;
    }
    results.push(await reloadOne(id));
  }
  post({ type: "reloadResult", requestId: msg.requestId, results });
  if (reloadSelf) {
    setTimeout(() => chrome.runtime.reload(), 200);
  }
}

async function reloadOne(id) {
  try {
    await chrome.management.get(id);
  } catch (e) {
    return { id, status: "not_installed" };
  }
  try {
    // Disabling and re-enabling an unpacked extension makes Chrome re-read
    // its files from disk.
    await chrome.management.setEnabled(id, false);
    await chrome.management.setEnabled(id, true);
    return { id, status: "reloaded" };
  } catch (e) {
    return { id, status: "error", error: String((e && e.message) || e) };
  }
}

async function handleList(msg) {
  let extensions = [];
  try {
    const all = await chrome.management.getAll();
    extensions = all
      .filter((e) => e.installType === "development" && e.type === "extension")
      .map((e) => ({
        id: e.id,
        name: e.name,
        version: e.version,
        enabled: e.enabled,
      }));
  } catch (e) {
    // Fall through with an empty list; the host reports it upstream.
  }
  post({ type: "listResult", requestId: msg.requestId, extensions });
}

chrome.runtime.onStartup.addListener(connect);
chrome.runtime.onInstalled.addListener(connect);
chrome.alarms.create(KEEPALIVE_ALARM, { periodInMinutes: 0.5 });
chrome.alarms.onAlarm.addListener((alarm) => {
  if (alarm.name === KEEPALIVE_ALARM) connect();
});
connect();
